const features = tableFeatures({
    columnFilteringFeature, globalFilteringFeature, rowSortingFeature, rowPaginationFeature,
    filteredRowModel: createFilteredRowModel(), sortedRowModel: createSortedRowModel(), paginatedRowModel: createPaginatedRowModel(),
    filterFns: {
        includeString: filterFn_includesString,
    },
    sortFns: {
        alphanumeric: sortFn_alphanumeric,
        text: sortFn_text
    }
});
const columns: Array<ColumnDef<typeof features, UserI>> = [
    {
        accessorKey: "userName",
        header: "User Name",
        cell: (info) => info.getValue(),
    },
    {
        accessorKey: "email",
        header: "Email Address",
        cell: (info) => info.getValue(),

    },
    {
        accessorKey: "role",
        header: "Role",
        cell: (info) => {
            const status = info.getValue<string>();
            if (status === "Admin") return <Badge variant="info">{status}</Badge>
        }

    },
    {
        accessorKey: "status",
        header: "Status",
        cell: (info) => {
            const status = info.getValue<string>();
            if (status == "Active") return <Badge variant="pending">{status}</Badge>
            else if (status == "InActive") return <Badge variant="insight">{status}</Badge>
        },

    },
    {
        accessorKey: "lastName",
        header: "Last Name",
        cell: (info) => info.getValue(),
    },
    {
        accessorKey: "phone",
        header: "Phone",
        cell: (info) => info.getValue(),

    },
    {
        accessorKey: "activeHours",
        header: "Hours spend in work",
        accessorFn: (row) => row.activeHours > 0 ? row.activeHours / row.week : 0,
        cell: ({ row }) => {
            return <ProgressionBar initialUnits={row.original.week} actualUnits={row.original.activeHours} />
        },

    },
    {
        accessorKey: "profileUrl",
        header: "Profile",
        cell: (info) => info.getValue(),

    }
]
export function UserTable() {
    const [globalFilter, setGlobalFilter] = useState<string>("");
    const [sorting, setSorting] = useState<{ id: string; desc: boolean }[]>([]);
    const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 2 });
    const table = useTable({
        features,
        columns,
        data: data,
        globalFilterFn: 'includeString',
        state: {
            globalFilter,
            sorting,
            pagination,
        },
        onGlobalFilterChange: setGlobalFilter,
        onSortingChange: setSorting,
        onPaginationChange: setPagination,
    });

    return (
        <section className="w-full min-w-0 space-y-5">

            {/* Header */}
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <div>
                    <h2 className="text-xl font-bold tracking-tight text-brand-deep dark:text-white sm:text-2xl">
                        User Management
                    </h2>

                    <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                        Manage user accounts, roles, and work activity.
                    </p>
                </div>

                <div className="flex items-center gap-2">
                    <span className="rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm text-gray-600 shadow-sm dark:border-gray-700 dark:bg-gray-900 dark:text-gray-300">
                        {table.getFilteredRowModel().rows.length} users
                    </span>
                </div>
            </div>

            {/* Table container */}
            <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm dark:border-gray-800 dark:bg-gray-950">

                {/* Search toolbar */}
                <div className="flex flex-col gap-3 border-b border-gray-200 p-4 dark:border-gray-800 sm:flex-row sm:items-center sm:justify-between">

                    <div className="relative w-full sm:max-w-sm">

                        {/* Search icon */}
                        <svg
                            xmlns="http://www.w3.org/2000/svg"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.8"
                            className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400"
                            aria-hidden="true"
                        >
                            <circle cx="11" cy="11" r="7" />
                            <path
                                strokeLinecap="round"
                                d="m16 16 4 4"
                            />
                        </svg>

                        <input
                            type="search"
                            value={globalFilter}
                            onChange={(e) => setGlobalFilter(e.target.value)}
                            placeholder="Search users..."
                            aria-label="Search users"
                            className="
                            w-full rounded-lg border border-gray-300
                            bg-white py-2.5 pl-9 pr-3 text-sm
                            text-gray-900 placeholder:text-gray-400
                            shadow-sm transition
                            hover:border-gray-400
                            focus:border-brand-forest
                            focus:outline-none focus:ring-2
                            focus:ring-brand-forest/20
                            dark:border-gray-700 dark:bg-gray-900
                            dark:text-white dark:placeholder:text-gray-500
                            dark:hover:border-gray-600
                        "
                        />
                    </div>

                    <p className="text-xs text-gray-500 dark:text-gray-400">
                        Click a column heading to sort.
                    </p>
                </div>

                {/* Responsive table */}
                <div className="w-full overflow-x-auto">
                    <table className="w-full min-w-[900px] border-collapse text-left text-sm">

                        {/* Column headings */}
                        <thead>
                            {table.getHeaderGroups().map((headerGroup) => (
                                <tr
                                    key={headerGroup.id}
                                    className="border-b border-gray-200 bg-gray-50 dark:border-gray-800 dark:bg-gray-900/70"
                                >
                                    {headerGroup.headers.map((header) => (
                                        <th
                                            key={header.id}
                                            scope="col"
                                            className="
                                            whitespace-nowrap px-5 py-4
                                            text-xs font-semibold uppercase
                                            tracking-wider text-gray-600
                                            dark:text-gray-300
                                        "
                                        >
                                            {header.isPlaceholder ? null : (
                                                <button
                                                    type="button"
                                                    onClick={
                                                        header.column.getCanSort()
                                                            ? header.column.getToggleSortingHandler()
                                                            : undefined
                                                    }
                                                    disabled={!header.column.getCanSort()}
                                                    className="
                                                    inline-flex items-center gap-2
                                                    rounded-sm text-left
                                                    transition-colors
                                                    hover:text-brand-forest
                                                    focus-visible:outline-none
                                                    focus-visible:ring-2
                                                    focus-visible:ring-brand-forest
                                                    disabled:cursor-default
                                                    disabled:hover:text-gray-600
                                                    dark:hover:text-brand-laurel
                                                    dark:disabled:hover:text-gray-300
                                                "
                                                >
                                                    <table.FlexRender header={header} />

                                                    <span
                                                        aria-hidden="true"
                                                        className="text-xs text-brand-forest dark:text-brand-laurel"
                                                    >
                                                        {{
                                                            asc: "↑",
                                                            desc: "↓",
                                                        }[
                                                            header.column.getIsSorted() as
                                                            "asc" | "desc"
                                                        ] ?? (
                                                                header.column.getCanSort()
                                                                    ? "↕"
                                                                    : ""
                                                            )}
                                                    </span>
                                                </button>
                                            )}
                                        </th>
                                    ))}
                                </tr>
                            ))}
                        </thead>

                        {/* Table rows */}
                        <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
                            {table.getRowModel().rows.length > 0 ? (
                                table.getRowModel().rows.map((row) => (
                                    <tr
                                        key={row.id}
                                        className="
                                        transition-colors duration-150
                                        hover:bg-gray-50
                                        dark:hover:bg-gray-900/70
                                    "
                                    >
                                        {row.getAllCells().map((cell) => (
                                            <td
                                                key={cell.id}
                                                className="
                                                whitespace-nowrap px-5 py-4
                                                align-middle text-sm
                                                text-gray-700
                                                dark:text-gray-300
                                            "
                                            >
                                                <table.FlexRender cell={cell} />
                                            </td>
                                        ))}
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td
                                        colSpan={table.getAllColumns().length}
                                        className="px-5 py-14 text-center"
                                    >
                                        <div className="flex flex-col items-center gap-2">
                                            <span className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                                                No users found
                                            </span>

                                            <p className="text-sm text-gray-500 dark:text-gray-400">
                                                Try another search term.
                                            </p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination footer */}
                <div className="
                flex flex-col gap-4 border-t border-gray-200
                bg-gray-50/70 p-4
                dark:border-gray-800 dark:bg-gray-900/40
                sm:flex-row sm:items-center sm:justify-between
            ">

                    <p className="text-sm text-gray-500 dark:text-gray-400">
                        Showing{" "}
                        <span className="font-semibold text-gray-800 dark:text-gray-200">
                            {table.getRowModel().rows.length}
                        </span>{" "}
                        rows on this page
                    </p>

                    <div className="flex flex-wrap items-center gap-3">

                        {/* Page size */}
                        <div className="flex items-center gap-2">
                            <label
                                htmlFor="page-size"
                                className="text-sm text-gray-500 dark:text-gray-400"
                            >
                                Rows per page
                            </label>

                            <select
                                id="page-size"
                                value={table.state.pagination.pageSize}
                                onChange={(e) =>
                                    table.setPageSize(Number(e.target.value))
                                }
                                className="
                                rounded-lg border border-gray-300
                                bg-white px-3 py-2 text-sm
                                text-gray-700 shadow-sm
                                focus:border-brand-forest focus:outline-none
                                focus:ring-2 focus:ring-brand-forest/20
                                dark:border-gray-700 dark:bg-gray-900
                                dark:text-gray-200
                            "
                            >
                                <option value={15}>15</option>
                                <option value={30}>30</option>
                                <option value={50}>50</option>
                                <option value={100}>100</option>
                            </select>
                        </div>

                        {/* Page navigation */}
                        <div className="flex items-center gap-2">
                            <button
                                type="button"
                                onClick={() => table.previousPage()}
                                disabled={!table.getCanPreviousPage()}
                                className="
                                rounded-lg border border-gray-300
                                bg-white px-3 py-2 text-sm font-medium
                                text-gray-700 shadow-sm transition
                                hover:bg-gray-100
                                disabled:cursor-not-allowed
                                disabled:opacity-40
                                dark:border-gray-700 dark:bg-gray-900
                                dark:text-gray-200 dark:hover:bg-gray-800
                            "
                            >
                                Previous
                            </button>

                            <button
                                type="button"
                                onClick={() => table.nextPage()}
                                disabled={!table.getCanNextPage()}
                                className="
                                rounded-lg border border-gray-300
                                bg-white px-3 py-2 text-sm font-medium
                                text-gray-700 shadow-sm transition
                                hover:bg-gray-100
                                disabled:cursor-not-allowed
                                disabled:opacity-40
                                dark:border-gray-700 dark:bg-gray-900
                                dark:text-gray-200 dark:hover:bg-gray-800
                            "
                            >
                                Next
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
}
export default UserTable;